"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["77973"],{86618(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.configuracao.tipo_conceito.codigo_ja_existe","status":409,"titulo":"C\xf3digo do tipo de conceito j\xe1 est\xe1 reservado"},"descricao":{"codigo":"uniplus.configuracao.tipo_conceito.codigo_ja_existe","requisitos":[],"oQueAconteceu":["A cria\xe7\xe3o de um tipo de conceito (`POST /api/configuracao/admin/tipos-conceito`) usou um `codigo` que j\xe1 pertence a outro tipo. O c\xf3digo \xe9 a chave natural do tipo e n\xe3o muda depois de criado. A compara\xe7\xe3o considera todos os tipos, ativos ou desativados, e \xe9 feita com o c\xf3digo como recebido.","Desativar um tipo tira o tipo de uso, mas n\xe3o libera o c\xf3digo: ele continua reservado. A resposta \xe9 a mesma quando a colis\xe3o \xe9 descoberta na confer\xeancia pr\xe9via e quando dois pedidos criam o mesmo c\xf3digo ao mesmo tempo e o banco recusa o segundo.","A recusa vem depois das confer\xeancias do corpo: com um corpo inv\xe1lido e um c\xf3digo j\xe1 usado, a resposta \xe9 a recusa do corpo (por exemplo, [nome do tipo de conceito obrigat\xf3rio](/erros/uniplus.configuracao.tipo_conceito.nome_obrigatorio)), e s\xf3 com o corpo v\xe1lido vem esta. Nada \xe9 gravado."],"comoResolver":["Use outro c\xf3digo. A API n\xe3o troca o c\xf3digo de um tipo existente e n\xe3o oferece opera\xe7\xe3o para reativar um tipo desativado: o c\xf3digo dele segue ocupado."],"ondeAparece":["Cria\xe7\xe3o de um tipo de conceito"]},"modulo":{"id":"configuracao","nome":"Configura\xe7\xe3o","assunto":"Tipo conceito"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"2b5f8240ef92ed3147f41ca40a325e729f45c7bd"}}')}}]);